     2	 * Authentication Middleware
     3	 * Supports JWT authentication and development mode
     4	 */
     5	
     6	const config = require('../config');
     7	const { verifyAccessToken, extractTokenFromHeader } = require('../utils/jwt');
     8	
     9	/**
    10	 * JWT Authentication Middleware
    11	 * Verifies Bearer token and extracts user info
    12	 * 
    13	 * Supports two modes:
    14	 * 1. Production Mode (AUTH_DEV_MODE=false): Must provide valid JWT token
    15	 * 2. Development Mode (AUTH_DEV_MODE=true): Allows skipping verification using x-customer-id header
    16	 */
    17	function authMiddleware(req, res, next) {
    18	  // Development mode: Allow x-customer-id header
    19	  if (config.auth.devMode) {
    20	    const customerId = req.headers['x-customer-id'];
    21	    if (customerId) {
    22	      req.customerId = customerId;
    23	      req.isDevMode = true;
    24	      return next();
    25	    }
    26	  }
    27	
    28	  // Get Authorization header
    29	  const authHeader = req.headers.authorization;
    30	  
    31	  // Extract token
    32	  const token = extractTokenFromHeader(authHeader);
    33	  
    34	  if (!token) {
    35	    // If in development mode and no token provided, use default user ID
    36	    if (config.auth.devMode) {
    37	      req.customerId = 'default-customer-id';
    38	      req.isDevMode = true;
    39	      return next();
    40	    }
    41	    
    42	    // Production mode must provide token
    43	    return res.status(401).json({ 
    44	      error: 'Authentication required. Please provide a valid Bearer token.' 
    45	    });
    46	  }
    47	
    48	  // Verify token
    49	  const payload = verifyAccessToken(token);
    50	  
    51	  if (!payload) {
    52	    return res.status(401).json({ 
    53	      error: 'Invalid or expired token' 
    54	    });
    55	  }
    56	
    57	  // Add user info to request object
    58	  req.customerId = payload.userId;
    59	  req.userEmail = payload.email;
    60	  req.isDevMode = false;
    61	
    62	  next();
    63	}
    64	
    65	/**
    66	 * Optional Authentication Middleware
    67	 * Verifies token if provided, otherwise continues (for public interfaces)
    68	 */
    69	function optionalAuthMiddleware(req, res, next) {
    70	  // Development mode
    71	  if (config.auth.devMode) {
    72	    const customerId = req.headers['x-customer-id'];
    73	    if (customerId) {
    74	      req.customerId = customerId;
    75	      req.isDevMode = true;
    76	    }
    77	  }
    78	
    79	  // Get Authorization header
