    33	  }
    34	});
    35	
    36	/**
    37	 * POST /orders
    38	 * Create new order (checkout process)
    39	 * Body: { books: [{ bookId, price, quantity }, ...] }
    40	 * 
    41	 * This operation will:
    42	 * 1. Create new order record
    43	 * 2. Clear checked out items from cart
    44	 */
    45	router.post('/', async (req, res, next) => {
    46	  try {
    47	    const { books } = req.body;
    48	
    49	    if (!books || !Array.isArray(books) || books.length === 0) {
    50	      return res.status(400).json({ 
    51	        error: 'Missing or invalid books array' 
    52	      });
    53	    }
    54	
    55	    // Generate order ID
    56	    const orderId = uuidv4();
    57	
    58	    // 1. Create order
    59	    const orderParams = {
    60	      TableName: dynamodb.ordersTable,
    61	      Item: {
    62	        customerId: req.customerId,
    63	        orderId: orderId,
    64	        orderDate: Date.now(),
    65	        books: books
    66	      }
    67	    };
    68	
    69	    await docClient.put(orderParams).promise();
    70	
    71	    // 2. Remove checked out items from cart
    72	    const deletePromises = books.map(book => {
    73	      const deleteParams = {
    74	        TableName: dynamodb.cartTable,
    75	        Key: {
    76	          customerId: req.customerId,
